skin:
#s98 .stage{background:#1d2b53;color:#fff;font-family:var(--mono)}
#s98 .d-nav{background:#0f1a33;border:2px solid #fff;border-radius:0}
#s98 .d-logo{font-weight:700;letter-spacing:.12em;color:#29ADFF}
#s98 .d-links span{opacity:.7;color:#c8d6f0;text-transform:uppercase}#s98 .d-links span:hover{opacity:1;color:#ffcd75}
#s98 .d-h{letter-spacing:.08em;color:#ffcd75;text-transform:uppercase}
#s98 .d-p{color:#c8d6f0}
#s98 .d-btn{background:#E43B44;color:#fff;border:2px solid #fff;border-radius:0;box-shadow:4px 4px 0 #0f1a33;font-weight:700;letter-spacing:.08em;text-transform:uppercase}
#s98 .d-btn:hover{transform:translate(2px,2px);box-shadow:2px 2px 0 #0f1a33}
#s98 .d-btn.ghost{background:#2ECC71;color:#0f1a33}
#s98 .d-input{background:#0f1a33;border:2px solid #29ADFF;border-radius:0;color:#29ADFF;text-transform:uppercase}
#s98 .d-badge{background:#29ADFF;color:#1D2B53;border-radius:0;font-weight:700}
#s98 .d-prog{background:#0f1a33;border:2px solid #fff;border-radius:0}#s98 .d-prog i{background:#2ECC71}
#s98 .d-card{background:#0f1a33;border:2px solid #fff;border-radius:0}
